local FunnelMaker = {}
local PRODUCTS = {
    tin_funnel = { name = "Kositrni lijak", tinCost = 1, time = 1, cost = 5, flowRate = 5, description = "Preprost kositrni lijak za pretoke." },
    copper_funnel = { name = "Bakreni lijak", copperCost = 1, time = 2, cost = 14, flowRate = 7, prestige = 1, description = "Bakreni lijak z dobno toplotno prevodnostjo." },
    brass_funnel = { name = "Medeninasti lijak", brassCost = 2, time = 3, cost = 32, flowRate = 9, prestige = 2, description = "Medeninasti lijak za vinarje in pivovarje." },
    silver_funnel = { name = "Srebrni lijak", silverCost = 2, time = 4, cost = 70, flowRate = 12, prestige = 5, description = "Srebrni lijak za lekarniško uporabo." },
    gold_rim_funnel = { name = "Zlatorobi lijak", goldCost = 1, brassCost = 2, time = 5, cost = 150, flowRate = 14, prestige = 9, happiness = 1, description = "Medeninasti lijak z zlatim robom." },
    royal_alchemical_funnel = { name = "Kraljevski alkimični lijak", goldCost = 2, silverCost = 2, glassCost = 1, time = 8, cost = 400, flowRate = 20, prestige = 22, happiness = 4, description = "Veliki kraljevski lijak z integriranim steklom za alkimične postopke." },
}
local BUILDINGS = {
    workshop = { name = "Lijakarska delavnica", cost = { gold = 190, wood = 100 }, upkeep = 4, qualityBonus = 5 },
    foundry = { name = "Livarna", cost = { gold = 600, wood = 200, stone = 150 }, upkeep = 15, qualityBonus = 15 },
    precision_room = { name = "Natančnostna soba", cost = { gold = 1100, wood = 250, stone = 250, silver = 20 }, upkeep = 25, qualityBonus = 22 },
    royal_funnel_atelier = { name = "Kraljevski atelje lijakov", cost = { gold = 3000, wood = 400, stone = 500, gold = 30 }, upkeep = 60, qualityBonus = 36, prestigeBonus = 17 },
}
FunnelMaker.tinStock = 14; FunnelMaker.copperStock = 12; FunnelMaker.brassStock = 8; FunnelMaker.silverStock = 5; FunnelMaker.goldStock = 3; FunnelMaker.glassStock = 6
FunnelMaker.productStock = {}; FunnelMaker.buildings = {}; FunnelMaker.maker = nil; FunnelMaker.activeMaking = {}; FunnelMaker.totalProducts = 0; FunnelMaker.dayTimer = 0
function FunnelMaker.init() FunnelMaker.tinStock=14; FunnelMaker.copperStock=12; FunnelMaker.brassStock=8; FunnelMaker.silverStock=5; FunnelMaker.goldStock=3; FunnelMaker.glassStock=6; FunnelMaker.productStock={}; FunnelMaker.buildings={}; FunnelMaker.maker=nil; FunnelMaker.activeMaking={}; FunnelMaker.totalProducts=0; FunnelMaker.dayTimer=0; print("[FunnelMaker] Royal Funnel Maker System initialized (6 products, 4 buildings)") end
function FunnelMaker.hireMaker(n,s) s=s or math.random(35,80); local c=250+s*5; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; FunnelMaker.maker={name=n or ("Lijakar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lijakar najet: %s (spretnost: %d)",FunnelMaker.maker.name,s),"success") end; return true end
function FunnelMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function FunnelMaker.build(id) local ok,e=FunnelMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(FunnelMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function FunnelMaker.getQualityBonus() local b=0; for _,bd in ipairs(FunnelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function FunnelMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.tinCost and FunnelMaker.tinStock<(d.tinCost or 0) then return false,"Premalo kositra" end; if d.copperCost and FunnelMaker.copperStock<(d.copperCost or 0) then return false,"Premalo bakra" end; if d.brassCost and FunnelMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and FunnelMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and FunnelMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.glassCost and FunnelMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if #FunnelMaker.buildings==0 then return false,"Potrebna delavnica" end; if not FunnelMaker.maker then return false,"Potreben lijakar" end; return true end
function FunnelMaker.make(pt,qty) qty=qty or 5; local ok,e=FunnelMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.tinCost then FunnelMaker.tinStock=FunnelMaker.tinStock-d.tinCost*qty end; if d.copperCost then FunnelMaker.copperStock=FunnelMaker.copperStock-d.copperCost*qty end; if d.brassCost then FunnelMaker.brassStock=FunnelMaker.brassStock-d.brassCost*qty end; if d.silverCost then FunnelMaker.silverStock=FunnelMaker.silverStock-d.silverCost*qty end; if d.goldCost then FunnelMaker.goldStock=FunnelMaker.goldStock-d.goldCost*qty end; if d.glassCost then FunnelMaker.glassStock=FunnelMaker.glassStock-d.glassCost*qty end; local t=d.time; if FunnelMaker.maker then t=math.max(1,t-math.floor(FunnelMaker.maker.skill/15)) end; table.insert(FunnelMaker.activeMaking,{id="funnel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,flowRate=d.flowRate or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function FunnelMaker.completeMaking(m) local q=1.0+(FunnelMaker.getQualityBonus()/100); if FunnelMaker.maker then q=q+(FunnelMaker.maker.skill/200) end; q=math.min(2.0,q); FunnelMaker.productStock[m.productType]=(FunnelMaker.productStock[m.productType] or 0)+m.quantity; FunnelMaker.totalProducts=FunnelMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if FunnelMaker.maker then FunnelMaker.maker.itemsMade=FunnelMaker.maker.itemsMade+m.quantity; if math.random()<0.15 then FunnelMaker.maker.skill=math.min(100,FunnelMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lijaki izdelani: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end end
function FunnelMaker.update(dt) if not _G.state then return end; FunnelMaker.dayTimer=FunnelMaker.dayTimer+dt; if FunnelMaker.dayTimer>=30 then FunnelMaker.dayTimer=0; for i=#FunnelMaker.activeMaking,1,-1 do local m=FunnelMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then FunnelMaker.completeMaking(m); table.remove(FunnelMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(FunnelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if FunnelMaker.maker then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function FunnelMaker.getStats() return {tinStock=FunnelMaker.tinStock,copperStock=FunnelMaker.copperStock,brassStock=FunnelMaker.brassStock,silverStock=FunnelMaker.silverStock,goldStock=FunnelMaker.goldStock,glassStock=FunnelMaker.glassStock,productStock=FunnelMaker.productStock,numBuildings=#FunnelMaker.buildings,hasMaker=FunnelMaker.maker~=nil,makerName=FunnelMaker.maker and FunnelMaker.maker.name or "—",makerSkill=FunnelMaker.maker and FunnelMaker.maker.skill or 0,activeMaking=#FunnelMaker.activeMaking,totalProducts=FunnelMaker.totalProducts} end
return FunnelMaker
